\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Effectiveness of a School-Based Intervention on Seasonal Influenza Absenteeism}
\author{R.~Osei, P.~Delgado, and H.~Virtanen}
\date{}

\begin{document}
\maketitle

\section{Methods}
\subsection{Study Design and Population}
We conducted a cluster-randomized controlled trial during the 2024--2025
influenza season. Forty-two primary schools in the metropolitan region
were randomized 1:1 to the intervention or control arm. The intervention
consisted of weekly hand-hygiene education sessions plus provision of
alcohol-based hand sanitizer in all classrooms. The primary outcome was
the rate of influenza-like-illness (ILI) absenteeism, defined as absence
episodes with reported fever and cough per 1000 student-days.

\subsection{Statistical Analysis}
We estimated the incidence rate ratio (IRR) of ILI absenteeism between
arms using a negative binomial regression model with school-level random
effects, adjusting for baseline absenteeism, school size, and neighborhood
deprivation index. All analyses followed the intention-to-treat
principle. Two-sided $p<0.05$ was considered statistically significant.

\begin{figure}[t]
\centering
\fbox{\rule[-2.6cm]{0pt}{5.2cm}\rule{7.5cm}{0pt}}
\caption{Participant flow through the trial. Of 42 randomized schools, 40
completed follow-up and were included in the primary analysis.}
\label{fig:flow}
\end{figure}

\section{Results}
Of the 42 randomized schools, 40 completed the study (two control schools
withdrew). The ILI absenteeism rate was 4.1 episodes per 1000
student-days in the intervention arm versus 5.8 in the control arm,
corresponding to an adjusted IRR of 0.71 (95\% CI 0.56--0.90;
$p=0.004$).

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\toprule
Outcome & Intervention & Control \\
\midrule
ILI absenteeism (per 1000 student-days) & 4.1 & 5.8 \\
All-cause absenteeism (per 1000 student-days) & 9.7 & 10.4 \\
\bottomrule
\end{tabular}
\caption{Absenteeism rates by study arm.}
\label{tab:rates}
\end{table}

A prespecified subgroup analysis suggested a larger effect in schools with
below-median baseline absenteeism (IRR 0.61, 95\% CI 0.44--0.85).

\end{document}
